    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private bool showCreateForm;
    private bool isCreating;
    private string? createError;
    private CreateShipmentRequest newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };

    private static readonly string[] Statuses =
        ["Processing", "In Transit", "Out for Delivery", "Delivered", "Delayed", "Returned"];

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipment()
    {
        createError = null;

        if (string.IsNullOrWhiteSpace(newShipment.Origin) ||
            string.IsNullOrWhiteSpace(newShipment.Destination) ||
            string.IsNullOrWhiteSpace(newShipment.RecipientName))
        {
            createError = "All fields are required.";
            return;
        }

        isCreating = true;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments?.Insert(0, created);
            newShipment = new CreateShipmentRequest { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
            showCreateForm = false;
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            isCreating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, string newStatus)
    {
        if (newStatus == shipment.Status) return;

        try
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
            if (newStatus == "Delivered")
                shipment.ActualDelivery = DateTime.UtcNow;
        }
        catch
        {
            // Revert on failure — re-fetch
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Processing" => "bg-secondary",
        "In Transit" => "bg-info text-dark",
        "Out for Delivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        "Returned" => "bg-dark",
        _ => "bg-secondary"
    };
}
