@page "/"

<PageTitle>ShipmentTracker</PageTitle>

<div class="text-center py-5">
    <h1 class="display-4">📦 ShipmentTracker</h1>
    <p class="lead mt-3">Real-time logistics tracking for dispatchers and customers.</p>
</div>

<div class="row g-4 mt-2">
    <div class="col-md-6">
        <div class="card h-100 shadow-sm">
            <div class="card-body text-center">
                <h3>🔍 Track a Shipment</h3>
                <p class="text-muted">Enter your tracking number to check status and estimated delivery.</p>
                <div class="input-group mb-3">
                    <input type="text" class="form-control" placeholder="e.g. SHP-20260620-10001"
                           @bind="trackingInput" @bind:event="oninput"
                           @onkeydown="HandleTrackKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
                </div>
                @if (!string.IsNullOrEmpty(trackingError))
                {
                    <div class="alert alert-warning">@trackingError</div>
                }
                @if (trackedShipment is not null)
                {
                    <div class="card mt-3">
                        <div class="card-body text-start">
                            <h5>@trackedShipment.TrackingNumber</h5>
                            <p><strong>Status:</strong> <span class="badge @GetStatusBadge(trackedShipment.Status)">@trackedShipment.Status</span></p>
                            <p><strong>From:</strong> @trackedShipment.Origin</p>
                            <p><strong>To:</strong> @trackedShipment.Destination</p>
                            <p><strong>Recipient:</strong> @trackedShipment.RecipientName</p>
                            <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                            <p><strong>Est. Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                            @if (trackedShipment.ActualDelivery.HasValue)
                            {
                                <p><strong>Delivered:</strong> @trackedShipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                            }
                        </div>
                    </div>
                }
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card h-100 shadow-sm">
            <div class="card-body text-center">
                <h3>📋 Dispatcher Dashboard</h3>
                <p class="text-muted">Manage shipments, update statuses, and create new shipments.</p>
                <a href="shipments" class="btn btn-outline-primary btn-lg">Go to Dashboard</a>
            </div>
        </div>
    </div>
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingInput = string.Empty;
    private string? trackingError;
    private ShipmentDto? trackedShipment;

    private async Task TrackShipment()
    {
        trackingError = null;
        trackedShipment = null;

        if (string.IsNullOrWhiteSpace(trackingInput))
        {
            trackingError = "Please enter a tracking number.";
            return;
        }

        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingInput.Trim());
        if (trackedShipment is null)
        {
            trackingError = $"No shipment found for \"{trackingInput}\".";
        }
    }

    private async Task HandleTrackKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Processing" => "bg-secondary",
        "In Transit" => "bg-info text-dark",
        "Out for Delivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        "Returned" => "bg-dark",
        _ => "bg-secondary"
    };
}

toolArgs.file_text:
@page "/track"

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">🔍 Track Your Shipment</h2>

<div class="row justify-content-center">
    <div class="col-md-8">
        <div class="input-group input-group-lg mb-4">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260620-10001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>

        @if (searched && shipment is null && !isSearching)
        {
            <div class="alert alert-warning">
                <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
                Please verify and try again.
            </div>
        }

        @if (shipment is not null)
        {
            <div class="card shadow">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h4 class="mb-0">@shipment.TrackingNumber</h4>
                    <span class="badge fs-6 @GetStatusBadge(shipment.Status)">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <dl>
                                <dt>From</dt>
                                <dd>@shipment.Origin</dd>
                                <dt>To</dt>
                                <dd>@shipment.Destination</dd>
                                <dt>Recipient</dt>
                                <dd>@shipment.RecipientName</dd>
                            </dl>
                        </div>
                        <div class="col-md-6">
                            <dl>
                                <dt>Shipped Date</dt>
                                <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                                <dt>Estimated Delivery</dt>
                                <dd class="@(shipment.Status == "Delayed" ? "text-danger fw-bold" : "")">
                                    @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")
                                </dd>
                                @if (shipment.ActualDelivery.HasValue)
                                {
                                    <dt>Delivered On</dt>
                                    <dd class="text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                                }
                            </dl>
                        </div>
                    </div>

                    @* Progress indicator *@
                    <div class="mt-3">
                        <div class="progress" style="height: 30px;">
                            <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                                 role="progressbar"
                                 style="width: @(GetProgressPercent(shipment.Status))%"
                                 aria-valuenow="@GetProgressPercent(shipment.Status)"
                                 aria-valuemin="0" aria-valuemax="100">
                                @shipment.Status
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [SupplyParameterFromQuery] public string? Id { get; set; }

    private string trackingNumber = string.Empty;
    private string? searchedNumber;
    private ShipmentDto? shipment;
    private bool searched;
    private bool isSearching;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrEmpty(Id))
        {
            trackingNumber = Id;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searched = false;
        shipment = null;

        try
        {
            searchedNumber = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
            searched = true;
        }
        finally
        {
            isSearching = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Processing" => "bg-secondary",
        "In Transit" => "bg-info text-dark",
        "Out for Delivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        "Returned" => "bg-dark",
        _ => "bg-secondary"
    };

    private static int GetProgressPercent(string status) => status switch
    {
        "Processing" => 20,
        "In Transit" => 50,
        "Out for Delivery" => 80,
        "Delivered" => 100,
        "Delayed" => 50,
        "Returned" => 100,
        _ => 0
    };

    private static string GetProgressBarClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger progress-bar-striped progress-bar-animated",
        "Returned" => "bg-dark",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };
}

